question.answer:
package main

import "fmt"

type Minutes int

type Ring struct {
	Bell   string
	Start  Minutes
	Length Minutes
}

func (m Minutes) Clock() string {
	return fmt.Sprintf("%02d:%02d", m/60, m%60)
}

func (r Ring) End() Minutes {
	return r.Start + r.Length
}

