question.answer:
package main

type Card struct {
	Patient string
	Visits  int
}

func (c Card) Stamped() Card {
	c.Visits++
	return c
}

func (c Card) Regular() bool {
	return c.Visits >= 3
}

testcode.text:
c := Card{Patient: "Ada", Visits: 0}
c = c.Stamped()
fmt.Println(c, c.Regular())

c := Card{Patient: "Bob", Visits: 2}
d := c.Stamped()
fmt.Println(d, d.Regular())

c := Card{Patient: "Cy", Visits: 2}
d := c.Stamped()
fmt.Println(c, d)

