question.answer:
package main

import "fmt"

type Meter struct {
	ID    string
	Units int
}

type Street struct {
	Name   string
	Meters []Meter
}

func (m *Meter) Advance(units int) {
	m.Units += units
}

func (m *Meter) Reading() string {
	return fmt.Sprintf("%s reads %d", m.ID, m.Units)
}

func (s *Street) AdvanceAll(units int) {
	for i := range s.Meters {
		s.Meters[i].Advance(units)
	}
}

func (s *Street) Total() int {
	total := 0
	for _, m := range s.Meters {
		total += m.Units
	}
	return total
}

func (s *Street) Find(id string) *Meter {
	for i := range s.Meters {
		if s.Meters[i].ID == id {
			return &s.Meters[i]
		}
	}
	return nil
}

testcode.text:
m := Meter{ID: "M1", Units: 10}
m.Advance(5)
fmt.Println(m.Reading(), m.Units)

s := Street{Name: "Tui", Meters: []Meter{{"M1", 10}, {"M2", 20}, {"M3", 0}}}
s.AdvanceAll(5)
fmt.Println(s.Total(), s.Meters)
